#!/usr/bin/env python3
"""Generate the language bindings from the ABI description (abi/vbm_json.abi.json). Usage: gen_bindings.py ROOT   (writes ROOT/bindings/...; scripts/gen-bindings.sh wraps it).
Everything the bindings contain that depends on the ABI is generated here: constants, struct layouts, function prototypes, the error types, and the tape reader. The only hand-written
files are the loaders (bindings/python/vbm_json/loader.py, bindings/rust/loader.rs: where the library is found) and the manifests. The bindings decide nothing about JSON: the tape
is read, never re-parsed (docs/decisions/0001-vbm-json.md: the boundary never decides)."""
import json, os, re, sys

HDR = "GENERATED by scripts/gen_bindings.py from abi/vbm_json.abi.json: do not edit (scripts/gen-bindings.sh regenerates; Tier 1 checks the committed copy equals the regenerated one)."

def camel(n):
    return n.capitalize()

# ---------------------------------------------------------------- Python
PY_SCALAR = {"u8": "ctypes.c_uint8", "u64": "ctypes.c_uint64", "int": "ctypes.c_int", "size": "ctypes.c_size_t", "ptr": "ctypes.c_void_p", "void": "None"}

def py_type(t):
    if t in PY_SCALAR: return PY_SCALAR[t]
    k, _, n = t.partition(":")
    if k == "ptr": return "ctypes.POINTER(%s)" % (PY_SCALAR[n] if n in PY_SCALAR else n)
    if k == "struct": return n
    if k == "fn": return "_cb_" + n
    raise SystemExit("gen_bindings: unknown abstract type " + t)

def gen_python(d):
    o = ['"""%s"""' % HDR, "import ctypes", "from . import loader", "",
         "ABI_VERSION = %d" % d["abi_version"], "TAPE_KIND_MASK = (1 << %d) - 1" % d["tape"]["kind_bits"], "TAPE_LEN_SHIFT = %d" % d["tape"]["len_shift"],
         "TAPE_NODE_WORDS = %d" % d["tape"]["node_words"], ""]
    for k in d["kinds"]: o.append("KIND_%s = %d" % (k["name"], k["value"]))
    for e in d["errors"]: o.append("%s = %d" % (e["name"], e["value"]))
    o.append("")
    for n, c in d["callbacks"].items():
        o.append("_cb_%s = ctypes.CFUNCTYPE(%s)" % (n, ", ".join([py_type(c["ret"])] + [py_type(p["type"]) for p in c["params"]])))
    o.append("")
    for s in d["structs"]:
        o += ["class %s(ctypes.Structure):" % s["name"], "    _fields_ = [" + ", ".join('("%s", %s)' % (f["name"], py_type(f["type"])) for f in s["fields"]) + "]", ""]
    o += ["_lib = loader.load()", ""]
    for f in d["functions"]:
        o += ["%s = _lib.%s" % (f["name"], f["name"]),
              "%s.argtypes = [%s]" % (f["name"], ", ".join(py_type(p["type"]) for p in f["params"])), "%s.restype = %s" % (f["name"], py_type(f["ret"])), ""]
    o += ["", "class Error(Exception):", '    """A non-OK result code of vbm_json_parse: .code is the ABI code, .name its name."""',
          "    def __init__(self, code, name):", '        super().__init__("vbm-json: %s (code %d)" % (name, code))', "        self.code = code", "        self.name = name", ""]
    errs = [e for e in d["errors"] if e["value"] != 0]
    for e in errs: o += ["class JSON%sError(Error):" % camel(e["name"]), "    pass", ""]
    o.append("_ERRORS = {" + ", ".join("%s: (JSON%sError, %r)" % (e["name"], camel(e["name"]), e["name"]) for e in errs) + "}")
    o += ["", "def _raise(code):", "    cls, name = _ERRORS.get(code, (Error, 'UNKNOWN'))", "    raise cls(code, name)", ""]
    o.append(PY_READER)
    return "\n".join(o) + "\n"

PY_READER = '''
class Number:
    """A JSON number as its lexeme (the library has no floats: -, digits, .digits, e[-]digits). int(n) and float(n) convert."""
    __slots__ = ("lexeme",)
    def __init__(self, lexeme): self.lexeme = lexeme
    def __eq__(self, other): return isinstance(other, Number) and self.lexeme == other.lexeme
    def __hash__(self): return hash(self.lexeme)
    def __repr__(self): return "Number(%r)" % self.lexeme
    def __int__(self): return int(self.lexeme)
    def __float__(self): return float(self.lexeme)


class Object(list):
    """A JSON object: a list of (key, value) pairs in input order, duplicate keys kept (dict(obj) keeps the last)."""


def _read(tape, number):
    """The tape as Python values: None, bool, number(lexeme str) (default Number), str, list, Object."""
    nw, nt = tape.nwords, tape.ntext
    if nw < TAPE_NODE_WORDS: _raise(INTERNAL)
    words = (ctypes.c_uint64 * nw).from_address(ctypes.addressof(tape.words.contents))
    text = ctypes.string_at(tape.text, nt) if nt else b""

    def node(i):
        if i + TAPE_NODE_WORDS > nw: _raise(INTERNAL)
        head, aux = words[i], words[i + 1]
        kind, n = head & TAPE_KIND_MASK, head >> TAPE_LEN_SHIFT
        i += TAPE_NODE_WORDS
        if kind == KIND_NULL: return None, i
        if kind == KIND_FALSE: return False, i
        if kind == KIND_TRUE: return True, i
        if kind == KIND_NUMBER or kind == KIND_STRING:
            if aux + n > nt: _raise(INTERNAL)
            raw = text[aux:aux + n]
            try: s = raw.decode("utf-8")
            except UnicodeDecodeError: _raise(INTERNAL)
            return (number(s) if kind == KIND_NUMBER else s), i
        if kind == KIND_ARRAY or kind == KIND_OBJECT:
            end = i - TAPE_NODE_WORDS + aux
            if aux < TAPE_NODE_WORDS or end > nw: _raise(INTERNAL)
            if kind == KIND_ARRAY:
                out = []
                for _ in range(n):
                    v, i = node(i)
                    out.append(v)
            else:
                out = Object()
                for _ in range(n):
                    if i + TAPE_NODE_WORDS > nw or words[i] & TAPE_KIND_MASK != KIND_STRING: _raise(INTERNAL)
                    k, i = node(i)
                    v, i = node(i)
                    out.append((k, v))
            if i != end: _raise(INTERNAL)
            return out, i
        _raise(INTERNAL)

    value, end = node(0)
    if end != nw: _raise(INTERNAL)
    return value


def parse(data, number=Number):
    """Parse bytes (RFC 8259, strict: see include/vbm_json.h) into Python values; raises an Error subclass (.code) on any non-OK result.
    number maps a number's lexeme (str) to a value; the default keeps the lexeme (Number)."""
    data = bytes(data)
    tape = vbm_json_tape()
    rc = vbm_json_parse(ctypes.cast(ctypes.c_char_p(data), ctypes.POINTER(ctypes.c_uint8)), len(data), None, ctypes.byref(tape))
    if rc != OK: _raise(rc)
    try:
        return _read(tape, number)
    finally:
        vbm_json_free(ctypes.byref(tape))


def _take(out):
    """The bytes of a vbm_json_bytes, copied out, and the block released."""
    try:
        return ctypes.string_at(out.data, out.len)
    finally:
        vbm_json_bytes_free(ctypes.byref(out))


def compact(data):
    """Parse bytes (as parse) and print the tape back with the library's printer: the compact form (no whitespace, numbers as their lexeme, strings escaped minimally). Raises an Error subclass on a non-OK result."""
    data = bytes(data)
    tape = vbm_json_tape()
    rc = vbm_json_parse(ctypes.cast(ctypes.c_char_p(data), ctypes.POINTER(ctypes.c_uint8)), len(data), None, ctypes.byref(tape))
    if rc != OK: _raise(rc)
    try:
        out = vbm_json_bytes()
        rc = vbm_json_print_tape(ctypes.byref(tape), None, ctypes.byref(out))
        if rc != OK: _raise(rc)
        return _take(out)
    finally:
        vbm_json_free(ctypes.byref(tape))


def escape_string(text):
    """The JSON string literal (quotes included) of the UTF-8 text (bytes, or str): the library's escaping. Raises JSONSyntaxError for bytes that are not valid UTF-8."""
    data = text.encode("utf-8") if isinstance(text, str) else bytes(text)
    out = vbm_json_bytes()
    rc = vbm_json_escape_string(ctypes.cast(ctypes.c_char_p(data), ctypes.POINTER(ctypes.c_uint8)), len(data), None, ctypes.byref(out))
    if rc != OK: _raise(rc)
    return _take(out)
'''

PY_INIT = '''"""%s"""
from ._generated import (parse, compact, escape_string, Error, Number, Object, ABI_VERSION, %s)
__all__ = ["parse", "compact", "escape_string", "Error", "Number", "Object", "ABI_VERSION", %s]
'''

def gen_python_init(d):
    names = ["JSON%sError" % camel(e["name"]) for e in d["errors"] if e["value"] != 0]
    return PY_INIT % (HDR, ", ".join(names), ", ".join('"%s"' % n for n in names))

# ---------------------------------------------------------------- Rust
RS_SCALAR = {"u8": "u8", "u64": "u64", "int": "c_int", "size": "usize"}

def rs_type(t, c=""):
    const = "const" if re.match(r"\s*const\b", c) else "mut"
    if t == "void": return "()"
    if t in RS_SCALAR: return RS_SCALAR[t]
    if t == "ptr": return "*%s c_void" % const
    k, _, n = t.partition(":")
    if k == "ptr": return "*%s %s" % (const, RS_SCALAR.get(n, n))
    if k == "struct": return n
    if k == "fn": return "Option<%s>" % ("Cb" + camel(n))
    raise SystemExit("gen_bindings: unknown abstract type " + t)

def split_params(c):
    inner = c.split("(", 1)[1].rsplit(")", 1)[0]
    return [p.strip() for p in inner.split(",")]

def gen_rust_sys(d):
    o = ["// " + HDR, "#![allow(non_camel_case_types, non_upper_case_globals, dead_code)]", "use std::os::raw::{c_int, c_void};", "",
         "pub const ABI_VERSION: u32 = %d;" % d["abi_version"], "pub const TAPE_KIND_MASK: u64 = (1 << %d) - 1;" % d["tape"]["kind_bits"],
         "pub const TAPE_LEN_SHIFT: u32 = %d;" % d["tape"]["len_shift"], "pub const TAPE_NODE_WORDS: usize = %d;" % d["tape"]["node_words"], ""]
    for k in d["kinds"]: o.append("pub const VBM_JSON_%s: u64 = %d;" % (k["name"], k["value"]))
    for e in d["errors"]: o.append("pub const VBM_JSON_%s: c_int = %d;" % (e["name"], e["value"]))
    o.append("")
    for n, c in d["callbacks"].items():
        ps = ", ".join("%s: %s" % (p["name"] if p["name"] != "ptr" else "p", rs_type(p["type"])) for p in c["params"])
        r = "" if c["ret"] == "void" else " -> " + rs_type(c["ret"])
        o.append('pub type Cb%s = unsafe extern "C" fn(%s)%s;' % (camel(n), ps, r))
    o.append("")
    for s in d["structs"]:
        o += ["#[repr(C)]", "#[derive(Clone, Copy)]", "pub struct %s {" % s["name"]]
        o += ["    pub %s: %s," % (f["name"], rs_type(f["type"], f["c"])) for f in s["fields"]]
        o += ["}", ""]
    o += ['#[link(name = "vbm_json")]', 'extern "C" {']
    for f in d["functions"]:
        cs = split_params(f["c"])
        ps = ", ".join("%s: %s" % (p["name"], rs_type(p["type"], c)) for p, c in zip(f["params"], cs))
        r = "" if f["ret"] == "void" else " -> " + rs_type(f["ret"])
        o.append("    pub fn %s(%s)%s;" % (f["name"], ps, r))
    o += ["}", ""]
    return "\n".join(o)

RS_LIB = '''// @@HDR@@
//! vbm-json: safe bindings over the C ABI of libvbm_json. `parse` returns a `Value` read from the tape; the library decides what is valid JSON and what a value is.
pub mod sys;
use sys::*;

/// A JSON value. A number is its lexeme (no floats in the library); an object keeps its members in input order, duplicate keys included.
#[derive(Debug, Clone, PartialEq, Eq)]
pub enum Value {
    Null,
    Bool(bool),
    Number(String),
    String(String),
    Array(Vec<Value>),
    Object(Vec<(String, Value)>),
}

/// A non-OK result of `vbm_json_parse` (`code` is the ABI code).
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum Error {
@@VARIANTS@@
    Unknown(i32),
}

impl Error {
    pub fn code(&self) -> i32 {
        match self {
@@CODES@@
            Error::Unknown(c) => *c,
        }
    }
    fn from_code(c: i32) -> Error {
        match c {
@@FROM@@
            c => Error::Unknown(c),
        }
    }
}

impl std::fmt::Display for Error {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result { write!(f, "vbm-json: {:?} (code {})", self, self.code()) }
}
impl std::error::Error for Error {}

struct Guard(vbm_json_tape);
impl Drop for Guard {
    fn drop(&mut self) { unsafe { vbm_json_free(&mut self.0) } }
}

/// Parse `input` (RFC 8259, strict) into a `Value`.
pub fn parse(input: &[u8]) -> Result<Value, Error> {
    let mut g = Guard(unsafe { std::mem::zeroed() });
    let rc = unsafe { vbm_json_parse(input.as_ptr(), input.len(), std::ptr::null(), &mut g.0) };
    if rc != VBM_JSON_OK { return Err(Error::from_code(rc)); }
    let t = &g.0;
    if t.nwords < TAPE_NODE_WORDS { return Err(Error::Internal); }
    let words = unsafe { std::slice::from_raw_parts(t.words, t.nwords) };
    let text: &[u8] = if t.ntext == 0 { &[] } else { unsafe { std::slice::from_raw_parts(t.text, t.ntext) } };
    let (v, end) = node(words, text, 0)?;
    if end != words.len() { return Err(Error::Internal); }
    Ok(v)
}

struct BytesGuard(vbm_json_bytes);
impl Drop for BytesGuard {
    fn drop(&mut self) { unsafe { vbm_json_bytes_free(&mut self.0) } }
}

fn take(g: &BytesGuard) -> Vec<u8> {
    if g.0.len == 0 { Vec::new() } else { unsafe { std::slice::from_raw_parts(g.0.data, g.0.len) }.to_vec() }
}

/// Parse `input` (as `parse`) and print the tape back with the library's printer: the compact form (no whitespace, numbers as their lexeme, strings escaped minimally).
pub fn compact(input: &[u8]) -> Result<Vec<u8>, Error> {
    let mut g = Guard(unsafe { std::mem::zeroed() });
    let rc = unsafe { vbm_json_parse(input.as_ptr(), input.len(), std::ptr::null(), &mut g.0) };
    if rc != VBM_JSON_OK { return Err(Error::from_code(rc)); }
    let mut o = BytesGuard(unsafe { std::mem::zeroed() });
    let rc = unsafe { vbm_json_print_tape(&g.0, std::ptr::null(), &mut o.0) };
    if rc != VBM_JSON_OK { return Err(Error::from_code(rc)); }
    Ok(take(&o))
}

/// The JSON string literal (quotes included) of the UTF-8 text: the library's escaping. `Error::Syntax` for bytes that are not valid UTF-8.
pub fn escape_string(text: &[u8]) -> Result<Vec<u8>, Error> {
    let mut o = BytesGuard(unsafe { std::mem::zeroed() });
    let rc = unsafe { vbm_json_escape_string(text.as_ptr(), text.len(), std::ptr::null(), &mut o.0) };
    if rc != VBM_JSON_OK { return Err(Error::from_code(rc)); }
    Ok(take(&o))
}

fn node(w: &[u64], text: &[u8], i: usize) -> Result<(Value, usize), Error> {
    if i + TAPE_NODE_WORDS > w.len() { return Err(Error::Internal); }
    let (head, aux) = (w[i], w[i + 1]);
    let (kind, n) = (head & TAPE_KIND_MASK, head >> TAPE_LEN_SHIFT);
    let mut i = i + TAPE_NODE_WORDS;
    match kind {
        VBM_JSON_NULL => Ok((Value::Null, i)),
        VBM_JSON_FALSE => Ok((Value::Bool(false), i)),
        VBM_JSON_TRUE => Ok((Value::Bool(true), i)),
        VBM_JSON_NUMBER | VBM_JSON_STRING => {
            let (a, n) = (aux as usize, n as usize);
            if a.checked_add(n).map_or(true, |e| e > text.len()) { return Err(Error::Internal); }
            let s = std::str::from_utf8(&text[a..a + n]).map_err(|_| Error::Internal)?.to_string();
            Ok((if kind == VBM_JSON_NUMBER { Value::Number(s) } else { Value::String(s) }, i))
        }
        VBM_JSON_ARRAY | VBM_JSON_OBJECT => {
            let aux = aux as usize;
            if aux < TAPE_NODE_WORDS || aux > w.len() - (i - TAPE_NODE_WORDS) { return Err(Error::Internal); }
            let end = i - TAPE_NODE_WORDS + aux;
            let mut items = Vec::new();
            let mut members = Vec::new();
            for _ in 0..n {
                if kind == VBM_JSON_ARRAY {
                    let (v, j) = node(w, text, i)?;
                    items.push(v);
                    i = j;
                } else {
                    if i + TAPE_NODE_WORDS > w.len() || w[i] & TAPE_KIND_MASK != VBM_JSON_STRING { return Err(Error::Internal); }
                    let (k, j) = node(w, text, i)?;
                    let (v, j) = node(w, text, j)?;
                    let k = match k { Value::String(s) => s, _ => return Err(Error::Internal) };
                    members.push((k, v));
                    i = j;
                }
            }
            if i != end { return Err(Error::Internal); }
            Ok((if kind == VBM_JSON_ARRAY { Value::Array(items) } else { Value::Object(members) }, i))
        }
        _ => Err(Error::Internal),
    }
}
'''

def gen_rust_lib(d):
    errs = [e for e in d["errors"] if e["value"] != 0]
    s = RS_LIB.replace("@@HDR@@", HDR)
    s = s.replace("@@VARIANTS@@", "\n".join("    %s," % camel(e["name"]) for e in errs))
    s = s.replace("@@CODES@@", "\n".join("            Error::%s => VBM_JSON_%s," % (camel(e["name"]), e["name"]) for e in errs))
    s = s.replace("@@FROM@@", "\n".join("            VBM_JSON_%s => Error::%s," % (e["name"], camel(e["name"])) for e in errs))
    return s

FILES = {
    "bindings/python/vbm_json/_generated.py": gen_python,
    "bindings/python/vbm_json/__init__.py": gen_python_init,
    "bindings/rust/src/sys.rs": gen_rust_sys,
    "bindings/rust/src/lib.rs": gen_rust_lib,
}

def main():
    root = sys.argv[1]
    d = json.load(open("abi/vbm_json.abi.json"))
    for p, f in FILES.items():
        path = os.path.join(root, p)
        os.makedirs(os.path.dirname(path), exist_ok=True)
        with open(path, "w") as fh: fh.write(f(d))
    print("gen_bindings: wrote %d files under %s/bindings" % (len(FILES), root))

if __name__ == "__main__":
    main()
